
USE [olist_dwh];
GO

--=========================================================================
-- create the seller dimension table
-- i am creating the seller dimension in the gold schema.
-- seller_key will be the surrogate key generated by sql server.
-- seller_id will be the business key used to identify each seller.
-- the zip code prefix will be used to connect sellers to dim_geography.
--=========================================================================

IF OBJECT_ID('[gold].[dim_seller]', 'U') IS NULL
BEGIN
    CREATE TABLE [gold].[dim_seller]
    (
        seller_key INT IDENTITY(1,1) NOT NULL,
        seller_id VARCHAR(50) NOT NULL,
        seller_zip_code_prefix CHAR(5) NOT NULL,

        CONSTRAINT PK_dim_seller
            PRIMARY KEY (seller_key)
    );
END;
GO

--=========================================================================
-- create a unique index for the seller business key
-- i am ensuring that each seller_id can only appear once
-- in the seller dimension.
-- this protects the dimension against duplicate seller records.
--=========================================================================

IF NOT EXISTS
(
    SELECT 1
    FROM sys.indexes
    WHERE name = 'UX_dim_seller_seller_id'
      AND object_id = OBJECT_ID('[gold].[dim_seller]')
)
BEGIN
    CREATE UNIQUE NONCLUSTERED INDEX UX_dim_seller_seller_id
    ON [gold].[dim_seller] (seller_id);
END;
GO

--=========================================================================
-- insert the unknown seller record
-- i am inserting an unknown seller with seller_key = -1.
-- this record will be used when a seller cannot be matched
-- to a record in the seller dimension.
-- identity_insert allows me to insert -1 manually.
-- the if not exists check prevents duplicate unknown records.
--=========================================================================

IF NOT EXISTS
(
    SELECT 1
    FROM [gold].[dim_seller]
    WHERE seller_key = -1
)
BEGIN
    SET IDENTITY_INSERT [gold].[dim_seller] ON;

    INSERT INTO [gold].[dim_seller]
    (
        seller_key,
        seller_id,
        seller_zip_code_prefix
    )
    VALUES
    (
        -1,
        'Unknown',
        '00000'
    );

    SET IDENTITY_INSERT [gold].[dim_seller] OFF;
END;
GO
